INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a662641a-5a05-412b-a6c7-babde2874a36', '21feff02-016d-46e2-bb9d-c27495133b1b', '110. óra: Testek térfogata', 'Téglatest és kocka térfogatának (V) kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "b39f5f2d-4c3e-4b75-818e-2077eb32dfb3", "text": "Mi a kocka térfogatának képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "42b0a6c6-d459-435c-b619-5dd4f0916081", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "2177e29c-71bf-447e-95d3-60adb6b2fc10", "text": "V = 6 * a²", "isCorrect": false}, {"id": "34660e69-a11c-4ee5-ba38-990045d2e3d3", "text": "V = 12 * a", "isCorrect": false}, {"id": "28df1be7-ccd4-4b34-80d6-2aefca72c690", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "423dd54f-aaea-4e87-ba8d-90673ee28d2a", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "843d4bba-78fa-4d23-9b7a-b6ed67cf1e21", "text": "V = a * b * c", "isCorrect": true}, {"id": "2b668303-23f7-4e8c-a17f-8d403aa6006c", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "007db31f-0ba3-45f9-8d37-495632ffdbc7", "text": "V = a * b", "isCorrect": false}, {"id": "61c70420-b11d-4d6b-84e7-4cf6a563743f", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "90e8bd4d-b503-46dd-b0c3-dc2f9a0f5e1e", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "ce9244f6-d587-4855-aa90-c88d50e40aeb", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "fdf63392-ec95-4a8b-a9c6-b5cbdad44769", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "3686aa7e-8789-48e7-9ad7-5e39add76039", "text": "Igaz", "isCorrect": true}, {"id": "1fd20c31-54da-4f87-a0b2-ba18406b99c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7c72f87f-562e-494b-9aec-c99c06292045", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "158ceff2-ebc4-4a93-be6b-5cecc57afec2", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b9ae19a9-26a3-478b-a150-03f77564bfc0', '21feff02-016d-46e2-bb9d-c27495133b1b', '111. óra: Projektóra', 'Épülettervezés I. - Vetületi képek megrajzolása, makett alaprajzának elkészítése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f26758b3-a0d3-488c-b9db-cf4754fd7fd8", "text": "Mit mutat meg egy épület felülnézete (alaprajza)?", "type": "multiple-choice", "options": [{"id": "b1082400-63bf-4776-883d-165117d79776", "text": "Az épület felülről látható elrendezését és méreteit", "isCorrect": true}, {"id": "433cfd2b-ff74-4fc8-bec7-8664163af58c", "text": "A tető színét", "isCorrect": false}, {"id": "1315e5d0-30ed-49f6-8d9f-6bd4adea8e7f", "text": "Az épület magasságát", "isCorrect": false}, {"id": "ebbafe39-cd9e-437d-9120-6008608dbec3", "text": "Az ablakok mintáját", "isCorrect": false}], "timeLimit": 15}, {"id": "758a8cd0-8acc-47d5-a54e-c2b86070eb88", "text": "Egy épület makettjének elkészítése segít a térbeli arányok megértésében.", "type": "true-false", "options": [{"id": "871020fe-e5de-4765-820c-7bc9110d4dd2", "text": "Igaz", "isCorrect": true}, {"id": "956539de-818a-4fa8-a177-c7977cb77e41", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c9510184-fc9e-4e3a-9343-929549a73534", "text": "Hány m² az 5 m x 6 m-es alaprajzú házalap területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "17c07822-86fa-48b2-9441-380e2577c8fd", "text": "A méretarányos rajz készítése elengedhetetlen az építészetben.", "type": "true-false", "options": [{"id": "3d0d1f1f-8add-426f-9514-99f6ccc8f3f3", "text": "Igaz", "isCorrect": true}, {"id": "e9fc48cd-f11a-4a3b-8d50-d78041027336", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dca464ed-3244-42c9-babe-373aafd948b7", "text": "Ha az 1:100 méretarányú rajzon a fal 5 cm, hány méter a valóságban? (5 * 100 cm)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "3d7a0ecb-d716-4c57-8dde-98590baf57ca", "text": "A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "09a15322-b8a6-456d-a766-c476e1bdf4c0", "text": "Igaz", "isCorrect": true}, {"id": "f01eeff2-74d8-4260-b0e4-de8f50c233b6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b30b993c-8c5d-4362-970b-c71f904fd51a", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e157b224-e599-4f8d-9c8d-aef55f962067', '21feff02-016d-46e2-bb9d-c27495133b1b', '112. óra: Projektóra II.', 'Épülettervezés II. - Makett megépítése kartonból, legóból, egységkockákból.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f9e68249-79ea-417e-80c5-8ab565a0f788", "text": "Hány darab 1 cm³-es kiskockára van szükség egy 3 cm x 4 cm x 5 cm-es épületmakett megépítéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "0252685c-6011-440f-a8c3-ab967f2c4193", "text": "Az épületmakett térfogata megegyezik a felhasznált egységkockák térfogatának összegevel.", "type": "true-false", "options": [{"id": "28c5f7e7-e451-4ed9-b2ce-e1f79687b62d", "text": "Igaz", "isCorrect": true}, {"id": "9ff6a733-54f0-4f0d-a410-c011d061b56b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2f93f79f-2e8f-4975-930f-e3eaf9f34c82", "text": "Melyik testből építhető fel a legkönnyebben téglatest alakú ház?", "type": "multiple-choice", "options": [{"id": "8a02a797-2519-416e-8bc9-fdb89a5d2e81", "text": "Egységkockákból / kartondobozból", "isCorrect": true}, {"id": "be7f2309-72e1-4efb-8967-9c6d50e35afc", "text": "Gömbökből", "isCorrect": false}, {"id": "6f3b5a9c-8b96-41f6-bb65-3eadd9bcb51b", "text": "Kúpokból", "isCorrect": false}, {"id": "e351b022-656e-4daa-ad72-2be5776dd0af", "text": "Hengerekből", "isCorrect": false}], "timeLimit": 15}, {"id": "718b5477-3e9c-403b-a566-59a376822f6b", "text": "A makett készítése során a stabil szerkezet kialakítása a cél.", "type": "true-false", "options": [{"id": "a0200587-9595-4d2d-94c1-af7b0e967506", "text": "Igaz", "isCorrect": true}, {"id": "bfab3839-7e5a-46e9-9ef8-3e3cb62682cb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5062a770-95e0-47b0-b74c-e494da4899d2", "text": "Mennyi a 2 cm élű kockákból álló 2x2x2-es házikó térfogata? (8 * 8 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "0fecc9b8-f83c-494a-940b-49c448b5ee54", "text": "A projektmunka kreatív megoldásokat ösztönöz.", "type": "true-false", "options": [{"id": "3bc0816e-9a63-4eaf-bdf0-38ea199613a2", "text": "Igaz", "isCorrect": true}, {"id": "b76b8b03-960d-4e3d-9277-3919d685b233", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8ac61968-7b17-474a-a934-359f5e7608bf", "text": "Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('11e4ac2b-cbf8-4e0d-9198-b0b7286664cf', '21feff02-016d-46e2-bb9d-c27495133b1b', '113. óra: Projektóra III.', 'Az elkészített projektek és makettek bemutatása, csoportértékelés.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "6ba6f926-c91e-422d-91c7-dddb9ae2ad87", "text": "Mi a projekt bemutatásának legfőbb értéke?", "type": "multiple-choice", "options": [{"id": "96e00d81-4425-4f4c-aade-f01882108f62", "text": "Az elvégzett munka, a mérések, számítások és az elkészült makett ismertetése", "isCorrect": true}, {"id": "30cdf133-2ea2-4ee7-a6bc-b56ddf216c62", "text": "Gyors befejezés elnémulva", "isCorrect": false}, {"id": "b881725d-9d9c-41a6-95ab-2c910dab913b", "text": "Más csoportok munkájának elrejtése", "isCorrect": false}, {"id": "91ace38f-6bc5-43db-b326-a2613a4560a0", "text": "Csak a színek felsorolása", "isCorrect": false}], "timeLimit": 15}, {"id": "fc70c890-e02a-4620-a494-56acbebc81b7", "text": "A prezentációs készség és a szaknyelv használata fontos részét képezi az értékelésnek.", "type": "true-false", "options": [{"id": "9cf8f95e-8c73-4e31-9f99-c989cac16d91", "text": "Igaz", "isCorrect": true}, {"id": "3eff7899-36f8-4e23-92a8-67bb452cf5ab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "65e615ee-06be-4938-b539-175fba9c36fc", "text": "Az önértékelés és a társak építő kritikája segít a fejlődésben.", "type": "true-false", "options": [{"id": "beadbc08-ca6d-4f8a-b597-62bd5996757d", "text": "Igaz", "isCorrect": true}, {"id": "8617007f-de56-428d-a987-78bbd5add52c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8da0bfe0-61be-4016-acea-7db4cb073017", "text": "Mennyi a 10 cm x 10 cm x 10 cm-es kockamakett térfogata literekben? (1000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "a21516b1-efb5-49c8-b83b-97fd3200048d", "text": "A projektmunka során a csoport minden tagjának részfeladatot kell vállalnia.", "type": "true-false", "options": [{"id": "e6874bbf-51a7-4192-ba2c-90dbc65afe2d", "text": "Igaz", "isCorrect": true}, {"id": "da8ad470-d86f-4c92-8644-ea4495adc651", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "72c53a10-aca0-4b3a-957c-c904950648b5", "text": "A térszemlélet fejlesztése elengedhetetlen a 3D-s tervezéshez.", "type": "true-false", "options": [{"id": "73bae701-a9b9-425f-8e90-69d93bbbd083", "text": "Igaz", "isCorrect": true}, {"id": "ac12130c-d620-4348-b3f3-52dc6e071ca4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "085462bc-fb62-4067-ad5f-a794603bfd9c", "text": "Mennyi 1 m³ dm³-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cf738687-8702-4bab-bc73-dc36cef351c5', '21feff02-016d-46e2-bb9d-c27495133b1b', '114. óra: Összefoglalás', 'A Kerület, terület, felszín és térfogat fejezet összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "88e68598-ea8c-4a09-b655-9f9361db7a2e", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "4f150347-6358-495e-be8a-a97998a33c57", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "cc86d010-e3c6-49b8-97a8-83a2e3744b76", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "08bdbaaf-93ee-476d-8103-d6e478734adc", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "8aa97e4c-4281-4240-be6c-2348d168c6bc", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "d89c1f88-2189-4137-b377-ce403ab75aa8", "text": "Igaz", "isCorrect": true}, {"id": "536391b7-ee0f-4fbb-a005-69d97ca53a39", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f27e6b92-30bc-4e41-9fae-b0d03832cc76", "text": "Hány cm² 1 m²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10000"}, {"id": "181cada2-a9d5-4105-9340-5b28a4cb4856", "text": "A kerület 1D (hosszúság), a terület 2D, a térfogat 3D mennyiség.", "type": "true-false", "options": [{"id": "69effc97-3f4c-4c53-868a-e60aef87df30", "text": "Igaz", "isCorrect": true}, {"id": "f6978343-ef37-4ff8-a3f7-d797a2082c77", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f1419643-5c1c-4184-adae-01cddbd51b24', '21feff02-016d-46e2-bb9d-c27495133b1b', '115. óra: Gyakorlóóra', 'Gyakorló feladatsor önálló megoldása a mérések témakörben.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "3f85f4ca-2aad-44b3-af33-a4ded3f15d45", "text": "Mennyi a 8 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "32"}, {"id": "bcecb39e-5397-4d2c-9fee-968d7e34022f", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "ef4e78dd-f351-456b-89d5-d8544c8f0d9f", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest felszíne? (2*(6+10+15) = 2*31)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "62"}, {"id": "42f45d87-74c3-4ceb-8c8b-b7ad67ab7cb3", "text": "A 1000 dm³ megegyezik 1 m³-rel.", "type": "true-false", "options": [{"id": "be96b865-dfa8-4e17-8593-dae47da85373", "text": "Igaz", "isCorrect": true}, {"id": "f299ea04-45e7-4096-b180-790f3cb0a39a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d1d43e34-e39f-4617-b4e5-8827b499c23f", "text": "Hány liter üdítő van egy 2500 cm³-es tartályban? (2,5 dm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "d9af94d2-edad-4822-a1b0-4b0ee442f2ee", "text": "A méréseknél az azonos mértékegységre való áttérés a sikeres számolás alapja.", "type": "true-false", "options": [{"id": "d21254c0-b789-4d1e-9973-2233440f3b05", "text": "Igaz", "isCorrect": true}, {"id": "e2cba6af-3abd-41b4-b8b4-2bc870b59efc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c4e94ca-a24f-4f05-9cbc-c1f05a1c026d", "text": "Mennyi a 6 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b3514e97-9e32-47ff-a588-08ff9f4e81a5', '21feff02-016d-46e2-bb9d-c27495133b1b', '116. óra: Feladatmegoldás', 'Hétköznapi mérésekkel, kerülettel, területtel és térfogattal kapcsolatos feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "d9135187-eaf5-489c-bdb2-564d0132c6a7", "text": "Egy 10 m x 8 m-es medence 2 m mély. Hány m³ víz fér a medencébe tele állapotban? (10 * 8 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "a41dd24e-65e9-4a2f-b4d1-1598f194be23", "text": "Hány liter víz fér a 160 m³-es medencébe? (160 * 1000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "c4ad3a03-291d-4b60-8c91-5c0e9dab5dca", "text": "Hány m² csempe kell a medence padlójának leburkolásához? (10 * 8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}, {"id": "8c4fa1db-2d34-4045-8e34-a8c18d47bc4d", "text": "A medence térfogata megadja a maximális vízkapacitást.", "type": "true-false", "options": [{"id": "e2aa6f68-35e0-4f75-afcb-7e2be544929a", "text": "Igaz", "isCorrect": true}, {"id": "a20eee88-f7e4-4bfe-bf5b-d5186dcd8955", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0980d923-8c9a-4b15-a3f0-7880e51cb07f", "text": "Mennyi a 4 m élű kocka alakú szoba térfogata? (m³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "9355ca76-eed0-45ee-a970-aae8652cd6a6", "text": "Mennyi a 4 m élű kocka alakú szoba felszíne? (m²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "d9fe7b16-af17-48a8-8ec0-9a028ad95d01", "text": "A gyakorlati feladatok megoldása felkészít a mindennapi életmérésekre.", "type": "true-false", "options": [{"id": "aabf4ced-e36f-45e1-ae06-06af9108e32d", "text": "Igaz", "isCorrect": true}, {"id": "1bffcfa2-3a8b-4283-bb17-adfd03a1c1e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ba3c9124-acf4-4925-bef7-9587fa210b3a', '21feff02-016d-46e2-bb9d-c27495133b1b', '117. óra: Témazáró dolgozat', 'Témazáró számonkérés a Kerület, terület, felszín és térfogat fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "86e06437-77d0-4a88-809e-57270f2cf414", "text": "1. Mennyi a 6 cm és 9 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "52371c89-951f-4bef-869d-304a7dcc2026", "text": "2. Mennyi a 6 cm és 9 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6ee8c91c-acfb-4887-b6f9-698c6722b274", "text": "3. Mennyi a 5 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "eed78d92-3fe7-4dad-ba9d-be69f6122c4b", "text": "4. Mennyi a 5 cm élű kocka térfogata? (cm³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "125"}, {"id": "7e05656f-6cbf-4d51-b0de-b1faf769db7d", "text": "5. Mennyi a 3 cm, 4 cm, 6 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}, {"id": "6a9387d6-26b7-4580-aa1d-b2dfcd616eeb", "text": "6. Hány cm² 4 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "7f329dd2-4523-4d20-a9ab-79ca75ddb60a", "text": "7. Hány dm³ 3 m³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "dc9e5fbf-fd96-4bc4-910c-e3245601de49", "text": "8. Hány liter víz fér el 5 dm³-es edényben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "b0410724-d9d4-4dd7-bdca-883c11f32519", "text": "9. A derékszögű háromszög területe a befogók szorzatának fele.", "type": "true-false", "options": [{"id": "23d1c178-1179-434d-bd71-9d48d314ae30", "text": "Igaz", "isCorrect": true}, {"id": "043ca688-5908-435c-97c7-30f0f016172c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c6aa83ba-42cc-4827-8c95-d17d4efd335f", "text": "10. Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9f020578-7f43-4fb4-b8a3-c0c9e201c421', '21feff02-016d-46e2-bb9d-c27495133b1b', '118. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése és a mérések összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "4bd4f2c4-5823-47c9-89a2-7bd4a02e5889", "text": "Mi volt a leggyakoribb hiba a felszín- és térfogatszámítás során?", "type": "multiple-choice", "options": [{"id": "1ab2890e-1297-4bea-8a74-b56969fb92c2", "text": "A képletek és mértékegységek (cm² vs cm³) összetévesztése", "isCorrect": true}, {"id": "b5a00a46-9a8c-442e-ab1f-41c878a959aa", "text": "A ceruza radírozása", "isCorrect": false}, {"id": "c864de38-f2b5-43cc-bd0e-e4a01dddd638", "text": "A számláló írása", "isCorrect": false}, {"id": "24074d34-8b85-4c20-a7ff-d5a8baa5a266", "text": "Az összeadás hiánya", "isCorrect": false}], "timeLimit": 15}, {"id": "75127246-6be9-4989-ade6-da56c516bcc1", "text": "A térfogat a test által elfoglalt térrész nagyságát jelenti.", "type": "true-false", "options": [{"id": "a67ce02c-5416-4260-b297-484b07de2958", "text": "Igaz", "isCorrect": true}, {"id": "0f125ebd-293c-48ca-91d8-2e5138f90bad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ce194b97-1596-4d97-a416-e4151310840f", "text": "Mennyi a 2 cm élű kocka térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "4dda0bdc-f9dc-4f5f-88c8-8a9c657915fc", "text": "Mennyi a 2 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "b4bdcf7f-d200-4077-98b9-58ddc88de6dc", "text": "A mértékegységek helyes megadása a válasz kötelező eleme.", "type": "true-false", "options": [{"id": "6982b91e-097b-4f4a-a5d3-47f02596fed2", "text": "Igaz", "isCorrect": true}, {"id": "44c651a0-71ab-45b1-8950-1dea65f9ab20", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4049c0a-7cfc-4edf-9df4-0c6467a20e44", "text": "Mennyi a 4 cm és 3 cm befogójú derékszögű háromszög területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "bada7053-be11-4974-aae4-d28cb5e99b9e", "text": "A hibajavítás segít a pontosabb tudás megszilárdításában.", "type": "true-false", "options": [{"id": "9258d9ee-188d-4f87-9c50-ec65e5950890", "text": "Igaz", "isCorrect": true}, {"id": "54c1f0ef-a661-41d3-9b69-4e9901a55902", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1d282b25-1ba1-4d4e-a3c7-ccc9b7d69fb6', '21feff02-016d-46e2-bb9d-c27495133b1b', '119. óra: Játék', 'Adatgyűjtési kifejezések, játékszabályok értelmezése, megfigyelés.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "f16a1a46-428b-4389-9db4-0c4eb139906a", "text": "Mi a statisztika fő célja?", "type": "multiple-choice", "options": [{"id": "7a92f62d-86ec-4e5d-8851-ee1d96cb7e97", "text": "Adatok gyűjtése, rendszerezése, ábrázolása és elemzése a döntéshozatalhoz", "isCorrect": true}, {"id": "bb2ac3c1-4718-4610-a16a-5423fedc011f", "text": "Színes rajzok készítése", "isCorrect": false}, {"id": "d824c0d7-7043-429d-9682-9f3fb8b45300", "text": "Számok törlése", "isCorrect": false}, {"id": "8fc55266-849f-4dbd-aaf6-a39a54510861", "text": "Csak a legnagyobb szám megtalálása", "isCorrect": false}], "timeLimit": 15}, {"id": "e812f8a4-f3bc-4f61-b69a-e78566087a31", "text": "Az adatok gyűjtése történhet megfigyeléssel, méréssel vagy kérdőívvel.", "type": "true-false", "options": [{"id": "fc5f74fa-4b1c-4ba5-aca8-8a73dbc67f48", "text": "Igaz", "isCorrect": true}, {"id": "877f56e1-bda6-414f-9528-c3a4c3c299c6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7028c2bc-fd1f-46f5-b987-044e5bb85b95", "text": "Melyik nem statisztikai adatgyűjtési módszer?", "type": "multiple-choice", "options": [{"id": "16cd91c3-2737-4c3b-a7c9-96441f7ae978", "text": "Alvás", "isCorrect": true}, {"id": "651634b2-92ec-4f83-a641-56279875c3c1", "text": "Kérdőíves felmérés", "isCorrect": false}, {"id": "0c4ca609-b8dd-42d9-aa1b-e1deb4f847bb", "text": "Hőmérséklet-mérés", "isCorrect": false}, {"id": "7620ded8-5f35-445b-acdb-24b431639ecb", "text": "Szavazás", "isCorrect": false}], "timeLimit": 15}, {"id": "a4f74e6a-4418-4a1c-84ad-b95a750e7c57", "text": "A gyűjtött adatokat áttekinthető módon táblázatba foglalhatjuk.", "type": "true-false", "options": [{"id": "051d7f6c-7212-4ce8-9117-8e1fae70f3d8", "text": "Igaz", "isCorrect": true}, {"id": "6eaa62f9-6904-4b90-9262-cea2e3e997f5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c31cf8da-1534-4c62-b916-f5e0cc996c36", "text": "Hány válaszlehetőség van egy ''igen/nem'' típusú kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "92a30889-1b59-426a-b1e3-57e04ea14815", "text": "A statisztikai mintavétel során a cél a pontos és torzításmentes adatszerzés.", "type": "true-false", "options": [{"id": "134be4f4-87de-4554-b3ca-105014cec773", "text": "Igaz", "isCorrect": true}, {"id": "93feeec8-18cc-48e2-bbd7-7b9c09889600", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "354a79b1-c269-4bde-8ed2-c64962d34b99", "text": "Az adatok rendszerezése megkönnyíti a döntéshozatalt.", "type": "true-false", "options": [{"id": "0e05bb10-2f6e-4011-9cd9-7cbc5e66b331", "text": "Igaz", "isCorrect": true}, {"id": "9cea2a05-384c-4293-aa74-685d20bb6b4a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());